.ds-graphite { --ds-cover-bg: var(--ds-canvas); --ds-hand-ink: var(--ds-ink-soft); --ds-hand-fill: var(--ds-turquoise); --ds-hand-fill2: var(--ds-river); --ds-hand-muted: var(--ds-tint); --ds-hand-ground: var(--ds-surface); --ds-hand-stroke: 1.5; --ds-hand-cap: round; --ds-hand-bg: var(--ds-canvas); --ds-hand-text-stroke: var(--ds-surface);
  --ds-tpl-edge: 1px solid var(--ds-hairline); --ds-tpl-radius: 8px; --ds-tpl-rule: 1px solid var(--ds-hairline); --ds-tpl-tile-shadow: none; --ds-tag-radius: 999px; --ds-slide-bg: var(--ds-surface); --ds-slide-title-bg: var(--ds-ink); --ds-slide-title-fg: var(--ds-on-ink); --ds-slide-split-a: var(--ds-turquoise); --ds-slide-split-b: var(--ds-tint); --ds-slide-split-b-fg: var(--ds-ink); --ds-slide-h-size: 8.5cqw;
  --ds-hero-bg: var(--ds-canvas); }
.ds-graphite .ds-section h2, .ds-graphite .ds-cover-name { font-family: var(--font-display); letter-spacing: -.03em; font-weight: 600; }
.ds-graphite .ds-chip { font-weight: 500; letter-spacing: 0; text-transform: none; border-color: var(--ds-hairline); opacity: 1; color: var(--ds-ink-soft); background: var(--ds-surface); border-radius: 8px; }
.ds-graphite .ds-eyebrow, .ds-graphite .t-label { text-transform: none; letter-spacing: 0; }
.ds-graphite .ds-eyebrow { font-size: 12px; font-weight: 500; color: var(--ds-ink-soft); }
.ds-graphite .ds-principle-n { color: var(--ds-ink-faint); font-weight: 500; }
.ds-graphite .ds-comp, .ds-graphite .ds-motif, .ds-graphite .ds-note, .ds-graphite .ds-voice, .ds-graphite .ds-hand-panel, .ds-graphite .ds-tpl, .ds-graphite .ds-tpl-kpi, .ds-graphite .ds-tpl-tile, .ds-graphite .ds-tpl-step, .ds-graphite .ds-tpl-wire, .ds-graphite .ds-tpl-flow, .ds-graphite .ds-tpl-stage { border-color: var(--ds-hairline); box-shadow: none; }
.ds-graphite .ds-tpl-kicker, .ds-graphite .ds-tpl-plan-sub { font-size: 12px; font-weight: 500; color: var(--ds-ink-soft); }
.ds-graphite .ds-tpl-stage-top, .ds-graphite .ds-tpl-stage-foot { text-transform: none; letter-spacing: 0; }
.ds-graphite .ds-tpl-tag { text-transform: none; letter-spacing: 0; font-weight: 500; padding-left: 8px; } .ds-graphite .ds-tpl-tag::before { content: ""; width: 6px; height: 6px; border-radius: 50%; background: currentColor; }
.ds-graphite .ds-tpl-ledger th { text-transform: none; letter-spacing: 0; font-weight: 600; font-size: 12px; background: var(--ds-sunk); padding-left: 10px; border-bottom: 1px solid var(--ds-hairline); } .ds-graphite .ds-tpl-ledger td { padding-left: 10px; }
.ds-graphite .ds-tpl-decision { border-left-width: 2px; border-left-color: var(--ds-ink); border-top: 1px solid var(--ds-hairline); border-right: 1px solid var(--ds-hairline); border-bottom: 1px solid var(--ds-hairline); }
.ds-graphite .ds-tpl-pull { border-top-width: 1px; border-top-color: var(--ds-hairline-strong); }
.ds-graphite .ds-tpl-dropcap { color: var(--ds-ink); }
.ds-graphite .ds-tpl-split-b { border: 1px solid var(--ds-hairline); }
.ds-graphite .h-num { font-family: var(--font-sans); font-weight: 600; letter-spacing: -.03em; fill: var(--ds-ink); }
.ds-graphite .h-text { fill: var(--ds-ink-soft); }
.ds-graphite .h-fill.h-outline-fill { fill: var(--ds-turquoise); fill-opacity: .82; stroke: none; }
.ds-graphite .h-fill2.h-outline-fill { fill: var(--ds-river); fill-opacity: .38; stroke: var(--ds-river); stroke-width: 1.5; }
.ds-graphite .gr-ground { fill: var(--ds-canvas); }
.ds-graphite .gr-frame { fill: var(--ds-surface); stroke: var(--ds-hairline); stroke-width: 1; }
.ds-graphite .gr-railbg { fill: var(--ds-sunk); } .ds-graphite .gr-railbg-s { fill: var(--ds-sunk); stroke: var(--ds-hairline); stroke-width: 1; }
.ds-graphite .gr-card { fill: var(--ds-surface); stroke: var(--ds-hairline); stroke-width: 1; } .ds-graphite .gr-field { fill: var(--ds-surface); stroke: var(--ds-hairline-strong); stroke-width: 1; }
.ds-graphite .gr-hair { stroke: var(--ds-hairline); stroke-width: 1; } .ds-graphite .gr-hair-dash { stroke: var(--ds-hairline-strong); stroke-width: 1; stroke-dasharray: 2 4; }
.ds-graphite .gr-grid { stroke: var(--ds-hairline); stroke-width: 1; stroke-dasharray: 2 4; } .ds-graphite .gr-zero { stroke: var(--ds-hairline-strong); stroke-width: 1; }
.ds-graphite .gr-line-h { fill: var(--ds-tint); } .ds-graphite .gr-line-on { fill: var(--ds-ink); opacity: .78; } .ds-graphite .gr-line-f { fill: var(--ds-hairline-strong); } .ds-graphite .gr-line-inv { fill: var(--ds-on-ink); }
.ds-graphite .gr-active { fill: var(--ds-tint); } .ds-graphite .gr-ink-sq, .ds-graphite .gr-k-ink { fill: var(--ds-ink); } .ds-graphite .gr-btn-ink { fill: var(--ds-ink); }
.ds-graphite .gr-pill-r { fill: var(--ds-canvas); stroke: var(--ds-hairline); stroke-width: 1; } .ds-graphite .gr-mini-r { fill: var(--ds-tint); } .ds-graphite .gr-add-r { fill: none; stroke: var(--ds-hairline-strong); stroke-width: 1; stroke-dasharray: 3 3; }
.ds-graphite .gr-k-date, .ds-graphite .gr-s1 { fill: var(--ds-turquoise); } .ds-graphite .gr-k-num, .ds-graphite .gr-k-num-c, .ds-graphite .gr-s2 { fill: var(--ds-river); } .ds-graphite .gr-k-red, .ds-graphite .gr-s3 { fill: var(--ds-alizarin); } .ds-graphite .gr-k-text { fill: var(--ds-carrot); }
.ds-graphite .gr-s1, .ds-graphite .gr-s2, .ds-graphite .gr-s3 { fill-opacity: .82; stroke: var(--ds-surface); stroke-width: 1; }
.ds-graphite .gr-k-date-o { fill: none; stroke: var(--ds-turquoise); stroke-width: 1.6; } .ds-graphite .gr-k-date-h { fill: none; stroke: var(--ds-turquoise); stroke-width: 1.6; stroke-linecap: round; }
.ds-graphite .gr-k-num-t { font-family: var(--font-sans); font-size: 16px; font-weight: 600; fill: var(--ds-river); } .ds-graphite .gr-k-text-t { font-family: var(--font-sans); font-size: 16px; font-weight: 600; fill: var(--ds-carrot); }
.ds-graphite .gr-qbar-r { fill: var(--ds-turquoise); fill-opacity: .3; }
.ds-graphite .gr-svg-label { font-family: var(--font-sans); font-size: 13px; fill: var(--ds-ink-soft); } .ds-graphite .gr-svg-on { font-family: var(--font-sans); font-size: 13px; font-weight: 500; fill: var(--ds-ink); } .ds-graphite .gr-svg-inv { font-family: var(--font-sans); font-size: 13px; font-weight: 500; fill: var(--ds-on-ink); }
.ds-graphite .gr-svg-cap { font-family: var(--font-sans); font-size: 11px; fill: var(--ds-ink-soft); } .ds-graphite .gr-svg-cap-on { font-family: var(--font-sans); font-size: 11px; font-weight: 600; fill: var(--ds-ink); }
.ds-graphite .gr-svg-num { font-family: var(--font-sans); font-size: 13px; font-weight: 500; fill: var(--ds-ink); font-variant-numeric: tabular-nums; }
.ds-graphite .gr-dot-live { fill: var(--ds-mark); } .ds-graphite .gr-dot-ok { fill: var(--ds-positive); } .ds-graphite .gr-dot-warn { fill: var(--ds-caution); } .ds-graphite .gr-dot-bad { fill: var(--ds-negative); } .ds-graphite .gr-dot-idle { fill: var(--ds-hairline-strong); } .ds-graphite .gr-dot-ring { opacity: .25; }
.ds-graphite .gr-btn { display: inline-flex; align-items: center; gap: 8px; font-family: var(--font-sans); font-size: 14px; font-weight: 500; line-height: 20px; padding: 7px 12px; border: 1px solid var(--ds-hairline-strong); border-radius: 8px; background: var(--ds-surface); color: var(--ds-ink); cursor: pointer; transition: border-color 120ms ease-out, background 120ms ease-out; }
.ds-graphite .gr-btn:hover { border-color: var(--ds-ink-faint); background: var(--ds-tint); } .ds-graphite .gr-btn:focus-visible { outline: none; box-shadow: var(--ds-focus-ring); }
.ds-graphite .gr-btn-primary { background: var(--ds-ink); border-color: var(--ds-ink); color: var(--ds-on-ink); } .ds-graphite .gr-btn-primary:hover { background: var(--ds-ink); border-color: var(--ds-ink); opacity: .88; }
.ds-graphite .gr-btn-ghost { border-color: transparent; background: transparent; } .ds-graphite .gr-btn-ghost:hover { border-color: transparent; background: var(--ds-tint); }
.ds-graphite .gr-btn-danger { color: var(--ds-negative); } .ds-graphite .gr-btn-danger:hover { background: var(--ds-negative-soft); border-color: var(--ds-negative); }
.ds-graphite .gr-kbd { display: inline-flex; align-items: center; justify-content: center; min-width: 20px; height: 20px; padding: 0 5px; border: 1px solid var(--ds-hairline); border-radius: 5px; background: var(--ds-sunk); box-shadow: var(--ds-shadow-key); font-family: var(--font-mono); font-size: 11px; color: var(--ds-ink-soft); }
.ds-graphite .gr-kbd-on { border-color: rgba(255,255,255,.25); background: rgba(255,255,255,.12); box-shadow: none; color: var(--ds-on-ink); }
.ds-graphite .gr-tag { display: inline-flex; align-items: center; gap: 6px; padding: 2px 10px 2px 8px; border-radius: 999px; font-size: 12px; font-weight: 500; line-height: 18px; background: var(--ds-tint); color: var(--ds-ink-soft); }
.ds-graphite .gr-tag i { position: relative; width: 6px; height: 6px; border-radius: 50%; background: currentColor; }
.ds-graphite .gr-tag-ok { background: var(--ds-positive-soft); color: var(--ds-positive); } .ds-graphite .gr-tag-warn { background: var(--ds-caution-soft); color: var(--ds-caution); } .ds-graphite .gr-tag-bad { background: var(--ds-negative-soft); color: var(--ds-negative); }
.ds-graphite .gr-tag-live { color: var(--ds-ink); } .ds-graphite .gr-tag-live i, .ds-graphite .gr-live i { background: var(--ds-mark); animation: gr-pulse 1.2s ease-in-out infinite; }
@keyframes gr-pulse { 50% { opacity: .35; } }
@media (prefers-reduced-motion: reduce) { .ds-graphite .gr-tag-live i, .ds-graphite .gr-live i, .ds-graphite .gr-act-live { animation: none; } }
.ds-graphite .gr-stat { display: grid; gap: 4px; padding: 16px 20px; min-width: 0; }
.ds-graphite .gr-stat-card { display: grid; margin-top: 24px; border: 1px solid var(--ds-hairline); border-radius: 12px; background: var(--ds-surface); } .ds-graphite .gr-stat-card .gr-stat { border-top: 1px solid var(--ds-hairline); } .ds-graphite .gr-stat-card .gr-stat:first-child { border-top: 0; }
.ds-graphite .ds-stats-card { margin-top: 0; width: 100%; }
.ds-graphite .gr-delta { font-size: 13px; color: var(--ds-ink-soft); } .ds-graphite .gr-up { color: var(--ds-positive); } .ds-graphite .gr-down { color: var(--ds-negative); }
.ds-graphite .gr-callout { padding: 12px 14px; border: 1px solid var(--ds-hairline); border-radius: 8px; font-size: 14px; line-height: 1.5; background: var(--ds-sunk); }
.ds-graphite .gr-callout strong { font-weight: 600; } .ds-graphite .gr-callout-ok { background: var(--ds-positive-soft); border-color: transparent; } .ds-graphite .gr-callout-bad { background: var(--ds-negative-soft); border-color: transparent; color: var(--ds-ink); }
.ds-graphite .gr-card-x { border: 1px solid var(--ds-hairline); border-radius: 12px; background: var(--ds-surface); padding: 16px 18px; min-width: 0; }
.ds-graphite .gr-card-head { display: flex; justify-content: space-between; align-items: center; gap: 12px; margin-bottom: 12px; flex-wrap: wrap; }
.ds-graphite .gr-qrow { display: grid; grid-template-columns: 90px 1fr; gap: 12px; align-items: center; padding: 6px 0; border-top: 1px solid var(--ds-hairline); font-size: 13px; }
.ds-graphite .gr-qbar { position: relative; display: block; height: 24px; } .ds-graphite .gr-qbar > span { position: absolute; right: 0; top: 0; bottom: 0; background: color-mix(in srgb, var(--ds-turquoise) 30%, transparent); } .ds-graphite .gr-qbar > b { position: absolute; right: 8px; top: 3px; font-weight: 500; font-variant-numeric: tabular-nums; }
.ds-graphite .gr-card-foot { display: flex; justify-content: space-between; align-items: center; gap: 12px; flex-wrap: wrap; margin-top: 12px; padding-top: 12px; border-top: 1px solid var(--ds-hairline); }
.ds-graphite .gr-faint { color: var(--ds-ink-faint); }
.ds-graphite .gr-sample { background: var(--ds-canvas); border-top: 1px solid var(--ds-hairline); border-bottom: 1px solid var(--ds-hairline); }
.ds-graphite .gr-shell { display: grid; grid-template-columns: minmax(0, 1fr); max-width: 1320px; margin: 0 auto; min-width: 0; }
.ds-graphite .gr-rail { display: flex; flex-direction: row; align-items: center; gap: 12px; padding: 10px 16px; border-bottom: 1px solid var(--ds-hairline); background: var(--ds-sunk); overflow-x: auto; }
.ds-graphite .gr-ws { display: inline-flex; align-items: center; gap: 8px; font-size: 15px; font-weight: 600; letter-spacing: -.02em; white-space: nowrap; }
.ds-graphite .gr-ws-sq { display: inline-flex; align-items: center; justify-content: center; width: 22px; height: 22px; border-radius: 6px; background: var(--ds-ink); color: var(--ds-on-ink); font-size: 12px; font-weight: 600; }
.ds-graphite .gr-pick { display: none; gap: 4px; } .ds-graphite .gr-pick-box { display: inline-flex; align-items: center; justify-content: space-between; gap: 10px; padding: 6px 10px; border: 1px solid var(--ds-hairline-strong); border-radius: 8px; background: var(--ds-surface); font-size: 13px; white-space: nowrap; }
.ds-graphite .gr-nav { display: flex; gap: 2px; align-items: center; } .ds-graphite .gr-nav-h { display: none; margin: 12px 8px 4px; color: var(--ds-ink-soft); }
.ds-graphite .gr-nav-item { padding: 6px 10px; border-radius: 8px; font-size: 14px; color: var(--ds-ink); white-space: nowrap; } .ds-graphite .gr-nav-on { background: var(--ds-tint); font-weight: 600; }
.ds-graphite .gr-rail-foot { display: none; align-items: center; gap: 8px; margin-top: auto; padding: 8px; border: 1px solid var(--ds-hairline); border-radius: 10px; background: var(--ds-surface); font-size: 13px; }
.ds-graphite .gr-rail-user { display: grid; line-height: 1.25; } .ds-graphite .gr-rail-user small { font-size: 11px; color: var(--ds-ink-soft); }
.ds-graphite .gr-avatar { display: inline-flex; align-items: center; justify-content: center; width: 26px; height: 26px; border-radius: 50%; background: var(--ds-ink); color: var(--ds-on-ink); font-size: 12px; font-weight: 600; }
.ds-graphite .gr-main { min-width: 0; padding: 0 20px 40px; }
.ds-graphite .gr-topbar { display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap; padding: 12px 0; border-bottom: 1px solid var(--ds-hairline); font-size: 13px; }
.ds-graphite .gr-sample-head { display: flex; justify-content: space-between; align-items: end; gap: 16px; flex-wrap: wrap; margin-top: 24px; } .ds-graphite .gr-sample-head h2 { margin: 0; }
.ds-graphite .gr-head-sub { margin: 6px 0 0; font-size: 13px; color: var(--ds-ink-soft); } .ds-graphite .gr-live { display: inline-flex; align-items: center; gap: 6px; color: var(--ds-ink); font-weight: 500; } .ds-graphite .gr-live i { width: 6px; height: 6px; border-radius: 50%; }
.ds-graphite .gr-shelves { display: grid; grid-template-columns: minmax(0, 1fr); margin-top: 16px; border: 1px solid var(--ds-hairline); border-radius: 12px; background: var(--ds-surface); overflow: hidden; }
.ds-graphite .gr-shelf { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; min-height: 46px; padding: 7px 10px 7px 14px; border-bottom: 1px solid var(--ds-hairline); } .ds-graphite .gr-shelf:last-child { border-bottom: 0; } .ds-graphite .gr-shelf > .t-label { width: 52px; color: var(--ds-ink-soft); }
.ds-graphite .gr-pill { display: inline-flex; align-items: center; gap: 6px; height: 32px; padding: 0 6px 0 10px; border: 1px solid var(--ds-hairline); border-radius: 8px; background: var(--ds-canvas); font-size: 13px; font-weight: 500; }
.ds-graphite .gr-kind { font-style: normal; font-weight: 600; } .ds-graphite [data-kind=date] > .gr-kind { color: var(--ds-turquoise); } .ds-graphite [data-kind=number] > .gr-kind { color: var(--ds-river); } .ds-graphite [data-kind=text] > .gr-kind { color: var(--ds-carrot); }
.ds-graphite .gr-mini { padding: 2px 8px; border-radius: 6px; background: var(--ds-tint); font-size: 12px; font-weight: 400; color: var(--ds-ink-soft); } .ds-graphite .gr-x { padding: 0 4px; color: var(--ds-ink-faint); font-weight: 400; }
.ds-graphite .gr-add { display: inline-flex; align-items: center; height: 32px; padding: 0 10px; border: 1px dashed var(--ds-hairline-strong); border-radius: 8px; font-size: 13px; color: var(--ds-ink-soft); }
.ds-graphite .gr-sample-grid { display: grid; gap: 16px; margin-top: 16px; }
.ds-graphite .gr-card-table { padding: 0; overflow: hidden; } .ds-graphite .gr-card-table .gr-card-head { padding: 14px 18px 0; }
.ds-graphite .gr-table { width: 100%; border-collapse: collapse; font-size: 13px; border: 0; }
.ds-graphite .gr-table th, .ds-graphite .gr-table td { border-left: 0; border-right: 0; border-top: 0; background: transparent; text-align: left; padding: 8px 14px; border-bottom: 1px solid var(--ds-hairline); white-space: nowrap; }
.ds-graphite .gr-table th { font-size: 12px; font-weight: 600; color: var(--ds-ink-soft); background: var(--ds-sunk); }
.ds-graphite .gr-table tbody tr:hover td { background: var(--ds-sunk); } .ds-graphite .gr-table tbody tr:last-child td { border-bottom: 0; }
.ds-graphite .gr-table .gr-r { text-align: right; font-variant-numeric: tabular-nums; }
.ds-graphite .gr-table .gr-num { background-image: linear-gradient(to left, color-mix(in srgb, var(--ds-turquoise) 30%, transparent) var(--w, 0%), transparent var(--w, 0%)); }
.ds-graphite .gr-activity { padding: 16px 20px 28px; border-top: 1px solid var(--ds-hairline); background: var(--ds-surface); }
.ds-graphite .gr-act-h { margin: 0 0 8px; }
.ds-graphite .gr-act { display: grid; grid-template-columns: 14px 1fr; gap: 10px; padding: 10px 0; border-top: 1px solid var(--ds-hairline); font-size: 13px; } .ds-graphite .gr-act div { display: grid; gap: 2px; } .ds-graphite .gr-act-t { font-size: 12px; color: var(--ds-ink-soft); }
.ds-graphite .gr-act-dot { width: 8px; height: 8px; margin-top: 5px; border-radius: 50%; background: var(--ds-hairline-strong); } .ds-graphite .gr-act-ok { background: var(--ds-positive); } .ds-graphite .gr-act-bad { background: var(--ds-negative); } .ds-graphite .gr-act-live { background: var(--ds-mark); animation: gr-pulse 1.2s ease-in-out infinite; }
@container (min-width: 760px) {
  .ds-graphite .gr-shell { grid-template-columns: 210px minmax(0, 1fr); }
  .ds-graphite .gr-rail { flex-direction: column; align-items: stretch; gap: 0; padding: 16px 12px; border-bottom: 0; border-right: 1px solid var(--ds-hairline); overflow: visible; min-height: 100%; }
  .ds-graphite .gr-ws { padding: 4px 8px 16px; } .ds-graphite .gr-pick { display: grid; padding: 0 4px 8px; } .ds-graphite .gr-nav { flex-direction: column; align-items: stretch; } .ds-graphite .gr-nav-h { display: block; } .ds-graphite .gr-rail-foot { display: flex; margin-top: 24px; }
  .ds-graphite .gr-main { padding: 0 24px 40px; }
  .ds-graphite .gr-stat-card { grid-template-columns: 1fr 1fr 1fr; } .ds-graphite .gr-stat-card .gr-stat { border-top: 0; border-left: 1px solid var(--ds-hairline); } .ds-graphite .gr-stat-card .gr-stat:first-child { border-left: 0; }
  .ds-graphite .gr-shelves { grid-template-columns: repeat(6, minmax(0, 1fr)); } .ds-graphite .gr-shelf { grid-column: span 3; border-left: 1px solid var(--ds-hairline); } .ds-graphite .gr-shelf:first-child { grid-column: span 2; border-left: 0; } .ds-graphite .gr-shelf-wide { grid-column: span 4; } .ds-graphite .gr-shelf:nth-child(3) { border-left: 0; } .ds-graphite .gr-shelf-full { grid-column: 1 / -1; border-left: 0; }
  .ds-graphite .gr-sample-grid { grid-template-columns: 1fr 1fr; }
  .ds-graphite .gr-activity { grid-column: 1 / -1; display: grid; grid-template-columns: 1fr 1fr; gap: 0 32px; padding: 16px 24px 24px; } .ds-graphite .gr-act-h { grid-column: 1 / -1; }
}
@container (min-width: 1100px) {
  .ds-graphite .gr-shell { grid-template-columns: 210px minmax(0, 1fr) 240px; }
  .ds-graphite .gr-activity { grid-column: auto; display: block; border-top: 0; border-left: 1px solid var(--ds-hairline); padding: 16px 20px 28px; }
  .ds-graphite .gr-sample-grid { grid-template-columns: 3fr 2fr; }
}
